\label{main thm}
	Let $D^{B}_{N}[\phi; \psi]$ be the bordered Toeplitz determinant with $\psi=q_1 \phi + q_2$ given by \eqref{general psi} and \eqref{q1 q2}, and $\phi$ of Szeg{\H o} type. Then, the following asymptotic behavior of $D^{B}_{N}[\phi; \psi]$ as $N \to \infty$ takes place 
\begin{equation}\label{main formula}

	  D^B_{N}\left[\phi ; \psi \right]   =  
	G[\phi]^{N} E[\phi]\left(F[\phi;\psi] + O(e^{-\mathfrak{c}N})\right),

	\end{equation} 
	where $G[\phi]$ and $E[\phi]$ are given by \eqref{G and E},
\begin{equation}\label{ConstantF2}
	F[\phi;\psi]  =	
	a_0+ b_0 [\log \phi]_{1} + 
	\hspace{-0.15cm}\sum^m_{j=1 \atop 0<|c_j|<1} \hspace{-0.15cm} b_j \frac{\alpha(c_j)}{\alpha(0)} 
	+	
         \frac{1}{\alpha(0)}\left( 
         \hat{a}_0-\hat{a}_1[\log \phi]_{-1} -
         \hspace{-0.15cm}\sum^{m}_{j=1  \atop |c_j|>1 }\hspace{-0.15cm}\frac{\hat{b}_j}{c_j} \alpha(c_j) \right),
	\end{equation}
	\begin{equation}
		\alpha(z):= \exp \left[ \frac{1}{2 \pi i } \int_{\mathbb{T}} \frac{\ln(\phi(\tau))}{\tau-z}d\tau \right],
	\end{equation}
and $\mathfrak{c}$ is some positive constant.

\label{thm 1.2}
	Let  $\psi(z)$ be a function which admits an analytic continuation in a neighborhood of the unit circle, and let 
	$\phi$ be of Szeg{\H{o}} type. Denote  by $\phi_{\pm}(z)$  the factors of a canonical Wiener-Hopf factorization of the symbol 
	$\phi(z)$, i.e.,  $\phi=\phi_-\phi_+$. Then
	\begin{equation}\label{main2}
		 D^B_{N}\left[\phi ; \psi \right]   =  
		G[\phi]^{N} E[\phi]\left( F[\phi;\psi]  + O(e^{-\mathfrak{c}N})\right),
	\end{equation}
	where $G[\phi]$ and $E[\phi]$ are given by \eqref{G and E},
	\begin{equation}\label{ConstantFthm1.2}
		F[\phi;\psi]=\frac{[\phi_-^{-1}\psi]_0}{[\phi_+]_0},
	\end{equation}
	and $\mathfrak{c}$ is some positive constant.

\label{th2}
Let $\langle \sigma_{0,0}\sigma_{N-1,N} \rangle$ be the next-to-diagonal two point correlation function
in the square lattice Ising model. Then,  in the low-temperature regime, the long-range order in the next-to-diagonal direction 

is the same as of the diagonal and horizontal ones,
i.e.,                          
\begin{equation}\label{"magnetization"}
\lim_{N \to \infty} \langle \sigma_{0,0}\sigma_{N-1,N} \rangle=  (1-k^{-2})^{1/4}.
\end{equation}

\label{th22}
The next-to-diagonal two point correlation function has, in the low-temperature regime $k>1$, the $N\to\infty$ asymptotics
\begin{align}\label{magnetization2}
	\langle \sigma_{0,0}\sigma_{N-1,N} \rangle &=
	(1-k^{-2})^{1/4}\left(1+\frac{1}{2\pi(1-k^{-2})}\Big(\frac{1}{C_v^2}+\frac{1}{k^2-1}\Big)N^{-2}k^{-2N}\Big(1+O(N^{-1})
	\Big)
	\right).
\end{align}

\label{elementary}
The following identity holds for the Bordered Toeplitz determinants
\begin{equation}\label{negative powers}
    D^B_{n+1}[\phi; z^{k}] = 0, \qquad k \in \mathbb{Z} \setminus \{ 0,1, \cdots, n \}.
\end{equation}

\label{psi=z}
Let $\phi$ be of Szeg{\H o} type. Then, as $n \to \infty$ we have
\begin{equation}\label{phi,z asymp1}
    D^B_{n+1}[\phi;z] =  D_n[\phi] \left(-\frac{1}{2\pi \mathrm{i}} \int_{\mathbb{T}} \ln(\phi(\tau)) \mathrm{d} \tau + O(e^{-\mathfrak{c}n})\right), 
\end{equation}
for some positive constant $\mathfrak{c}$.

Expanding $\alpha(z)$, given by \eqref{45}, as $z \to \infty $ we get 
\begin{equation}\label{expansion of al(z) at infinity}
    \alpha(z) = 1 - \frac{a_0}{2\pi \mathrm{i} z} - \left( \frac{a_1}{2\pi \mathrm{i}} + \frac{a^2_0}{8 \pi^2} \right) \frac{1}{z^2} + \cdots , \qquad z \to \infty,
\end{equation}
where
\begin{equation}
    a_k := \int_{\mathbb{T}} \tau^k \ln \left(\phi(\tau)\right) \mathrm{d} \tau. 
\end{equation}
Also from \eqref{X in terms of R exact}, and \eqref{R asymp} we have

\begin{equation}\label{X11}
    X_{11}(z;n) = \alpha(z)z^n\left(1 + \frac{ O(e^{-2\mathfrak{c}n})}{ 1+|z| } \right), \qquad z \in \Omega_{\infty}, \qquad n \to \infty.
\end{equation}
Combining \eqref{border-z-X-RHP}, \eqref{expansion of al(z) at infinity} and \eqref{X11} gives \eqref{phi,z asymp1}.

The bordered Toeplitz determinant $D^B_{n+1}[\phi,\displaystyle \frac{1}{z-c}]$, is encoded into $X$-RHP data described by
\begin{equation}\label{psi=1/z-c}
    D^B_{n+1}[\phi;\frac{1}{z-c}] = \begin{cases}
    0, & |c|<1, \\
    -c^{-n-1}D_{n}[\phi]X_{11}(c;n), & |c|>1,
    \end{cases}
\end{equation}
where $D_{n}[\phi]$ is given by \eqref{ToeplitzDet} and $X_{11}$ is the $11$ entry of the solution to  \textbf{RH-X1} through  \textbf{RH-X3}.

The case of $|c|<1$ is obvious due to \eqref{q_kj}. Consider $|c|>1$. Recalling that $X_{11}(z;n)=\kappa^{-1}_nQ_n(z)$, from \eqref{Toeplitz OP 1} and \eqref{ka_n} we have
  \begin{equation}
        X_{11}(z;n) = \frac{1}{D_n[\phi]} \mathrm{det} \begin{pmatrix}
\phi_0 & \phi_{-1} & \cdots & \phi_{-n} \\
\phi_1 & \phi_{0} & \cdots & \phi_{-n+1} \\
\vdots & \vdots & \cdots & \vdots \\
\phi_{n-1} & \phi_{n-2} & \cdots & \phi_{-1} \\
1 & z & \cdots & z^{n}
\end{pmatrix}.
\end{equation}
Therefore from \eqref{q_kj}
\begin{equation}
    \begin{split}
        -c^{-n-1}D_{n}[\phi]X_{11}(c;n) & = \mathrm{det} \begin{pmatrix}
\phi_0 & \phi_{-1} & \cdots & \phi_{-n} \\
\phi_1 & \phi_{0} & \cdots & \phi_{-n+1} \\
\vdots & \vdots & \cdots & \vdots \\
\phi_{n-1} & \phi_{n-2} & \cdots & \phi_{-1} \\
-c^{-n-1} & -c^{-n} & \cdots & -c
\end{pmatrix} \\ & = \mathrm{det} \begin{pmatrix}
\phi_0 & \phi_{-1} & \cdots & \phi_{-n} \\
\phi_1 & \phi_{0} & \cdots & \phi_{-n+1} \\
\vdots & \vdots & \cdots & \vdots \\
\phi_{n-1} & \phi_{n-2} & \cdots & \phi_{-1} \\
q_{0,n} & q_{0,n-1} & \cdots & q_{0,0}
\end{pmatrix} \equiv D^B_{n+1}[\phi,q_0].
    \end{split}
\end{equation}

\label{cor 1}
We have
\begin{equation}\label{228}
	D^B_{n+1}\left[\phi;\displaystyle a+\frac{b_0}{z}+\sum^{m}_{j=1}\frac{b_j }{z-c_j}\right] = D_n[\phi] \left(a -\sum^{m}_{j=1  \atop |c_j|>1 }b_j c^{-n-1}_jX_{11}(c_j;n)\right),
\end{equation}
and for a Szeg{\H o} type $\phi$
\begin{equation}\label{229}
D^B_{n+1}\left[\phi;\displaystyle a+\frac{b_0}{z}+\sum^{m}_{j=1}\frac{b_j }{z-c_j}\right] = G[\phi]^{n} E[\phi] \left(a -\sum^{m}_{j=1  \atop |c_j|>1 }\frac{b_j}{c_j} \alpha(c_j)\right)\left( 1 + O(e^{-\mathfrak{c}n})\right),
\end{equation}
 as $n \to \infty$, where 	\begin{equation}\label{al al}
 \alpha(z):= \exp \left[ \frac{1}{2 \pi i } \int_{\mathbb{T}} \frac{\ln(\phi(\tau))}{\tau-z}d\tau \right],
 \end{equation} $G[\phi]$ and $E[\phi]$ are given by \eqref{G and E} and  $\mathfrak{c}$ is some positive constant.

\label{lem2.2} Let $\psi_0:=q_0\phi$, where $q_0$ is defined in \eqref{q1 and q2}, with $c \neq 0$. Then the bordered Toeplitz determinant $D^{B}_n[\phi;\psi_0]$ can be written in terms of the following data from the solution of the X-RHP:
\begin{equation}\label{bdToep-RHP-q0}
    D^{B}_{n+1}[\phi;\psi_0] = - \frac{1}{c}D_{n+1}[\phi]+ \frac{1}{c} D_{n}[\phi] X_{12}(c,n),
\end{equation}
where $D_{n}[\phi]$ is given by \eqref{ToeplitzDet} and $X_{12}$ is the $12$ entry of the solution to  \textbf{RH-X1} through  \textbf{RH-X3}.

Note that \begin{equation*}
    \psi_{0,j} = \int_{\mathbb{T}} z^{-j} \psi_0(z) \frac{\mathrm{d} z}{2 \pi \mathrm{i} z} = \int_{\mathbb{T}} z^{-j}  \frac{1}{z(z-c)} \phi(z) \frac{\mathrm{d} z}{2 \pi \mathrm{i}}, 
\end{equation*}thus
\begin{equation}
  \psi_{0,j}  = -\frac{1}{c}  \int_{\mathbb{T}} z^{-j}  \phi(z) \frac{\mathrm{d} z}{2 \pi \mathrm{i} z} + \frac{1}{c}  \int_{\mathbb{T}}   \frac{z^{-j}\phi(z)}{(z-c)}  \frac{\mathrm{d} z}{2 \pi \mathrm{i}}  = -\frac{1}{c}\phi_j +
  \frac{1}{c}  \int_{\mathbb{T}}   \frac{z^{-j}\phi(z)}{(z-c)}  \frac{\mathrm{d} z}{2 \pi \mathrm{i}}.
\end{equation}
Now, observe that
\begin{equation*}
    D^{B}_{n+1}[\phi,\psi_0] = \mathrm{det} \begin{pmatrix}
\phi_0 & \phi_{-1} & \cdots & \phi_{-n} \\
\phi_1 & \phi_{0} & \cdots & \phi_{-n+1} \\
\vdots & \vdots & \cdots & \vdots \\
\phi_{n-1} & \phi_{n-2} & \cdots & \phi_{-1} \\
\psi_{0,n} & \psi_{0,n-1} & \cdots & \psi_{0,0}
\end{pmatrix} \end{equation*} \begin{equation*}
 =  \frac{1}{c}  \mathrm{det} \begin{pmatrix}
\phi_0 & \phi_{-1} & \cdots & \phi_{-n} \\
\phi_1 & \phi_{0} & \cdots & \phi_{-n+1} \\
\vdots & \vdots & \cdots & \vdots \\
\phi_{n-1} & \phi_{n-2} & \cdots & \phi_{-1} \\
-\phi_n + \int_{\mathbb{T}}   \frac{z^{-n}\phi(z)}{(z-c)}  \frac{\mathrm{d} z}{2 \pi \mathrm{i}} & -\phi_{n-1} + \int_{\mathbb{T}}   \frac{z^{-n+1}\phi(z)}{(z-c)}  \frac{\mathrm{d} z}{2 \pi \mathrm{i}} & \cdots & -\phi_0 + \int_{\mathbb{T}}   \frac{\phi(z)}{(z-c)}  \frac{\mathrm{d} z}{2 \pi \mathrm{i}}
\end{pmatrix} =
\end{equation*}
\begin{equation}\label{AA}
    -\frac{1}{c} \mathrm{det} \begin{pmatrix}
\phi_0 & \phi_{-1} & \cdots & \phi_{-n} \\
\phi_1 & \phi_{0} & \cdots & \phi_{-n+1} \\
\vdots & \vdots & \cdots & \vdots \\
\phi_{n-1} & \phi_{n-2} & \cdots & \phi_{-1} \\
\phi_n  & \phi_{n-1} & \cdots & \phi_0
\end{pmatrix} + \frac{1}{c}\mathrm{det} \begin{pmatrix}
\phi_0 & \phi_{-1} & \cdots & \phi_{-n} \\
\phi_1 & \phi_{0} & \cdots & \phi_{-n+1} \\
\vdots & \vdots & \cdots & \vdots \\
\phi_{n-1} & \phi_{n-2} & \cdots & \phi_{-1} \\
 \int_{\mathbb{T}}   \frac{z^{-n}\phi(z)}{(z-c)}  \frac{\mathrm{d} z}{2 \pi \mathrm{i}} &  \int_{\mathbb{T}}   \frac{z^{-n+1}\phi(z)}{(z-c)}  \frac{\mathrm{d} z}{2 \pi \mathrm{i}} & \cdots &  \int_{\mathbb{T}}   \frac{\phi(z)}{(z-c)}  \frac{\mathrm{d} z}{2 \pi \mathrm{i}}
\end{pmatrix}.
\end{equation}
Now note that, using \eqref{Toeplitz OP 1} and \eqref{ka_n} we have

\begin{equation}
    \kappa_n^{-1} \zeta^{-n}Q_n(\zeta) = \frac{1}{D_n[\phi]} \mathrm{det} \begin{pmatrix}
\phi_0 & \phi_{-1} & \cdots & \phi_{-n} \\
\phi_1 & \phi_{0} & \cdots & \phi_{-n+1} \\
\vdots & \vdots & \cdots & \vdots \\
\phi_{n-1} & \phi_{n-2} & \cdots & \phi_{-1} \\
\zeta^{-n} & \zeta^{-n+1} & \cdots & 1
\end{pmatrix}.
\end{equation}
Combining this equation with \eqref{Toeplitz-OP-solution} yields
\begin{equation}\label{X12 bordered}
X_{12}(z;n) = \frac{1}{D_n[\phi]} \mathrm{det} \begin{pmatrix}
\phi_0 & \phi_{-1} & \cdots & \phi_{-n} \\
\phi_1 & \phi_{0} & \cdots & \phi_{-n+1} \\
\vdots & \vdots & \cdots & \vdots \\
\phi_{n-1} & \phi_{n-2} & \cdots & \phi_{-1} \\
\int_{\mathbb{T}}  \frac{\zeta^{-n} \phi(\zeta)}{\zeta-z} \frac{\mathrm{d} \zeta}{2\pi \mathrm{i}} & \int_{\mathbb{T}}  \frac{\zeta^{-n+1} \phi(\zeta)}{\zeta-z} \frac{\mathrm{d} \zeta}{2\pi \mathrm{i}} & \cdots & \int_{\mathbb{T}}  \frac{\phi(\zeta)}{\zeta-z} \frac{\mathrm{d} \zeta}{2\pi \mathrm{i}}
\end{pmatrix}.
\end{equation}
Thus, using \eqref{AA} and \eqref{X12 bordered} we arrive at \eqref{bdToep-RHP-q0}.

\label{cor 2}
	We have
	\begin{equation}\label{235}
	D^B_{n+1}\left[\phi;\displaystyle\left( a+\sum^{m}_{j=1}\frac{b_j z}{z-c_j}\right)\phi \right] =aD_{n+1}[\phi]+ D_n[\phi] \sum^{m}_{j=1}b_j X_{12}(c_j;n),
	\end{equation}
	and for a Szeg{\H o} type $\phi$
	\begin{equation}\label{236}
	D^B_{n+1}\left[\phi;\displaystyle\left( a+\sum^{m}_{j=1}\frac{b_j z}{z-c_j}\right)\phi \right] = G[\phi]^{n+1} E[\phi] \left(a+\frac{1}{G[\phi]}\sum^{m}_{j=1  \atop |c_j|<1 }b_j \alpha(c_j)\right)\left( 1 + O(e^{-\mathfrak{c}n})\right),
	\end{equation}
	as $n \to \infty$, where $\alpha$ is defined in \eqref{al al},  $G[\phi]$ and $E[\phi]$ are given by  \eqref{G and E}, and  $\mathfrak{c}$ is some positive constant.

\eqref{235} directly follows from \eqref{bdToep-RHP-q0}, \eqref{border,phi,phi}, and \eqref{linear-combination}. For the asymptotic statement, notice that from  \eqref{R_k's are small},  \eqref{X in terms of R exact} and \eqref{R asymp} we have \begin{equation}\label{237}
	X_{12}(c;n) = \begin{cases}
	\alpha(c) (1+O(e^{-\mathfrak{c}n})), & |c|<1, \\
	R_{1,12}(c;n)\alpha^{-1}(c)c^{-n}(1+O(e^{-\mathfrak{c}n})), & |c|>1,
	\end{cases}
	\end{equation}
	 as $n \to \infty$,	where $R_{1,12}$ is given by  \eqref{R1}. Now \eqref{236} follows from \eqref{Szego Theorem}, \eqref{G and E}, \eqref{235}, \eqref{237}, and \eqref{R_k's are small}.

\label{analogue of lemma 2.2 for c=0}
We have the following identity\footnote{Throughout the paper we occasionally use $\tilde{f}(z)$, to denote $\displaystyle f(z^{-1})$.} \begin{equation}
    D^B_{n}[\phi;\frac{1}{z}\phi] = - D^B_{n+1}[\Tilde{\phi};z],
\end{equation} 
and hence for a Szeg{\H o} type $\phi$
\begin{equation}\label{phi,z^-1phi asymp}
     D^B_{n}[\phi;\frac{1}{z}\phi] = \frac{1}{2\pi \mathrm{i}} G[\phi]^{n} E[\phi]\left( \int_{\mathbb{T}} \ln(\Tilde{\phi}(\tau))  \mathrm{d} \tau + O(e^{-\mathfrak{c}n}) \right),
\end{equation}
as $n \to \infty$, where $G[\phi]$ and $E[\phi]$ are given by  \eqref{G and E}, and  $\mathfrak{c}$ is some positive constant.

\label{psi=z^k phii}
	For $\psi = z^k \phi$, $k=0,1,\cdots, n$, we have
	\begin{equation}\label{psi=z^kphi}
	D^B_n[\phi,z^k\phi] = \begin{cases} 
	D_n[\phi], & k=0, \\
	0, & k=1,\cdots,n-1,\\
	(-1)^{n-1}D_n[z\phi], & k=n.
	\end{cases}
	\end{equation}

\label{intas} The following estimates take place,
\begin{equation}\label{intas1}
\begin{split}
\frac{1}{2\pi i} \int_{\Gamma_0}a(\tau;n) 
\frac{d\tau}{\tau-z} =
-\frac{1}{\sqrt{\pi}}\alpha^{2}(k^{-1})\frac{\sqrt{k-k^{-1}}}{k}
\frac{1}{k^{-1} -z}k^{-n -1/2}n^{-1/2} \left(1+O\left(\frac{1}{n}\right)\right), \quad n \to \infty, 
\end{split}
\end{equation}
for all $|z| > \rho^{-1}$, and
\begin{equation}\label{intas2}
\displaystyle \frac{1}{4\pi^2}\int_{\Gamma_1}b(\mu;n)\left[\int_{\Gamma_0}a(\tau;n)
\frac{d\tau}{\tau-\mu}\right]\frac{d\mu}{\mu-z} =
-\frac{1}{2\pi}
\frac{1}{k^{-1} - k}\frac{1}{k-z}
k^{-2n}n^{-2}\left( 1+ O\left(\frac{1}{n}\right)\right), \quad n \to \infty,
\end{equation}
for all $|z| < \rho$.

Consider first the single, $a$ - integral. It can be deformed to the integral over the 
segment $[0, k^{-1}]$ so that we would have,
\begin{equation}\label{131313}
	\frac{1}{2\pi i} \int_{\Gamma_0}a(\tau;n) 
	\frac{d\tau}{\tau-z} = -\frac{1}{\pi } \int_{0}^{k^{-1}}\tau^n(k^{-1} - \tau)^{-1/2}\Phi(\tau)d\tau,
\end{equation}
where
$$
\Phi(\tau) = \sqrt{\tau k^{-1}}\sqrt{k-\tau}\frac{\alpha^{2}(\tau)}{\tau - z}
$$
is holomorphic at  $\tau = k^{-1}$. Let
\begin{equation}\label{141414}
	\Phi(\tau) = \sum_{l=0}^{\infty}d_l(\tau-k^{-1})^l, \quad d_0 = \Phi(k^{-1}) = 
	\frac{1}{k}\sqrt{k-k^{-1}}\frac{\alpha^{2}(k^{-1})}{k^{-1} - z},
\end{equation}
be the Taylor series of $\Phi(\tau)$ at $\tau = k^{-1}$. Then, according to the standard Watson Lemma type arguments, we arrive at the asymptotic  formula,
\begin{equation}\label{hN1}
\frac{1}{2\pi i} \int_{\Gamma_0}a(\tau;n) 
\frac{d\tau}{\tau-z} \sim -\frac{1}{\pi} \sum_{l=0}^{\infty}d_l\int_{0}^{k^{-1}}\tau^n(k^{-1}-\tau)^{l-1/2}d\tau,
\end{equation}
and this asymptotic is uniform in any compact subset of $\{z: |z| > \rho^{-1}\}$ and, in particular, for $z \in \Gamma_1$.
For the integrals in the right hand side of (\ref{hN1}), we have,
\begin{equation}\label{151515}
	\begin{split}
	\int_{0}^{k^{-1}}\tau^n(k^{-1}-\tau)^{l-1/2}d\tau  & = k^{-n-l-1/2}\int_{0}^{1}t^n(1-t)^{l-1/2}dt = k^{-n-l-1/2}B(n+1, l+1/2) \\ & = k^{-n-l-1/2}\frac{\Gamma(n+1)\Gamma(l+1/2)}{\Gamma(n+l+3/2)} = k^{-n-l-1/2}\Gamma(l+1/2)n^{-l-1/2}\left(1+O\left(\frac{1}{n}\right)\right),
	\end{split}
\end{equation}
as $n \to \infty$, and hence
\begin{equation}\label{hN2}
\frac{1}{2\pi i} \int_{\Gamma_0}a(\tau;n) 
\frac{d\tau}{\tau-z} = 
-\frac{1}{\sqrt{\pi}}\alpha^{2}(k^{-1})\frac{\sqrt{k-k^{-1}}}{k}
\frac{1}{k^{-1} -z}k^{-n -1/2}n^{-1/2}\left(1+O\left(\frac{1}{n}\right)\right),
\end{equation}
as $n \to \infty$, uniformly in any compact subset of $\{z: |z| > \rho^{-1}\}$. This is the estimate (\ref{intas1}).

Consider now the double integral (\ref{intas2}). In view of (\ref{hN2}) we have at once that{\footnote{ We are also
taking into account that $\int_{\Gamma_1}b(\mu)f(\mu) d\mu = O(k^{-n})$ for any bounded $f(\mu)$ analytic in the annulus, $\rho -\epsilon
<|\mu| < k+\epsilon$.}} 
\begin{equation}\label{121212}\begin{split}
	\displaystyle \frac{1}{4\pi^2}\int_{\Gamma_1}b(\mu;n)\left[\int_{\Gamma_0}a(\tau;n)
\frac{d\tau}{\tau-\mu}\right]\frac{d\mu}{\mu-z} & = -\frac{i}{2\pi^{3/2}}\alpha^{2}(k^{-1})\frac{\sqrt{k-k^{-1}}}{k}k^{-n -1/2}n^{-1/2}
 \\ & \times \left[\int_{\Gamma_1}b(\mu;n)\frac{d\mu}{(k^{-1} - \mu)(\mu - z)} + O\left(\frac{k^{-n}}{n}\right)\right], \quad n \to \infty.
\end{split}
\end{equation}
Applying to the $b$ -integral in the right hand side of the last equation the same arguments as we 
used for derivation of the estimate (\ref{hN2}), we  obtain that
 \begin{equation}\label{hN3}
 \int_{\Gamma_1}b(\mu;n)\frac{d\mu}{(k^{-1} - \mu)(\mu - z)} = -i\sqrt{\pi}\alpha^{-2}(k)\frac{1}{(k-z)\sqrt{k-k^{-1}}}
\frac{1}{k^{-1} -k}k^{-n +3/2}n^{-3/2}\left(1+O\left(\frac{1}{n}\right)\right),
\end{equation}
as $
n \to \infty
$, uniformly in any compact subset of $\{z: |z| <  \rho\}$. This in turns yields the estimate, 
$$
\displaystyle \frac{1}{4\pi^2}\int_{\Gamma_1}b(\mu;n)\left[\int_{\Gamma_0}a(\tau;n)
\frac{d\tau}{\tau-\mu}\right]\frac{d\mu}{\mu-z} = -\frac{1}{2\pi}
\frac{\alpha^2(k^{-1})\alpha^{-2}(k)}{k^{-1} - k}\frac{1}{k-z}
k^{-2n}n^{-2}\left( 1+ O\left(\frac{1}{n}\right)\right), \quad n \to \infty,
$$
which, taking into account that 
$$
\alpha^{-1} (z)\alpha(z^{-1}) =1,
$$
implies (\ref{intas2})

\label{p.Bordered.Cramer}
	Let  $\phi,\psi\in L^1(\mathbb{T})$, and assume that $T_N(\phi)$ is invertible.
	Then
	\begin{equation}\label{Bordered.Cramer}
	D_N^B[\phi;\psi]=
	D_N[\phi]\cdot e_0^T T_N^{-1}(\phi) T_N(\psi) e_0.
	\end{equation}

Via a rearrangement of rows and columns in \eqref{btd} (or, more formally, by multiplying with a ``flip matrix'' from both sides) we see that
	\begin{equation}\label{btd-2}
	D^{B}_{N}[\phi; \psi] = \mathrm{det} \begin{pmatrix}
	\psi_0& \phi_{-1} & \cdots & \phi_{-N-1} \\
	\psi_{1}& \phi_0 & \ddots  & \vdots \\
	\vdots & \vdots & \ddots &  \phi_{-1} \\
	\psi_{N-1} & \phi_{N-2} & \cdots  &\phi_{0}
	\end{pmatrix}.
	\end{equation}
	By observing that $T_N(\psi)e_0$  is the column vector
	$(\psi_0,\dots,\psi_{N-1})^T$, the statement follows from Cramer's rule.

\label{thm3.3}
Let $\phi\in C(\mathbb{T})$                                                             
have a continuous canonical 
Wiener-Hopf factorization $\phi=\phi_-\phi_+$. Assume that  $\psi=\phi p_++p_-$ with $p_+\in H^2(\mathbb{T})$ and $p_-\in H^2_-(\mathbb{T})$. Then 
\begin{equation}\label{f.F}
	F[\phi;\psi]=[p_+]_0.
\end{equation}
In particular, 
\begin{align}\label{3.15}
F[\phi; \left( a_{0} + a_1z + \frac{b_0}{z}+\sum_{j=1}^m \frac{b_j z}{z-c_j}\right)\phi] 
&= 
a_{0}+ b_0[\log \phi]_{1} + \sum_{|c_j|<1} b_j\frac{\phi_+(c_j)}{\phi_+(0)},
\\
\label{3.16}
F[\phi; \left(a_0+a_1z+ \frac{b_0}{z} + \sum_{j=1}^m \frac{b_j }{z-c_j}\right)] 
&= 
\frac{a_0}{\phi_+(0)\phi_-(\infty)} - a_1\frac{[\log \phi]_{-1}}{\phi_{+}(0)\phi_-(\infty)}   -\sum_{|c_j|>1} \frac{b_j}{c_j\phi_+(0)\phi_-(c_j)}.
\end{align}

\label{thm.3.1}
	Let $\phi$ have a continuous canonical Wiener-Hopf factorization $\phi=\phi_-\phi_+$, and assume that  $\psi=\phi p_++p_-$ with $p_+\in H^2(\mathbb{T})$ and $p_-\in H^2_-(\mathbb{T})$. Then 
\begin{equation}\label{eqn.expan}
	F_N[\phi;\psi]=
	F[\phi;\psi]-\frac{1}{[\phi_+]_0}\cdot  e_0^T T(\lambda^{-1}_N)(I-K_N)^{-1} T(\phi_- z^{-N} p_+)e_0.
\end{equation}

\label{c.32b}
	Let $\phi(z)$ be analytic an nonvanishing function on the annulus $a_1<|z|<b_1$ with winding number zero,
	and let $\psi(z)$ be analytic on the annulus $a_2<|z|<b_2$, where $a_i<1<b_i$. Then, for each
	$\kappa$ with $\kappa>a_1\max\{b_1^{-1},b_2^{-1}\}$, we have 
	\begin{align}\label{FN.asym2}
	F_N[\phi;\psi] 
	&= F[\phi;\psi]+O(\kappa^N),\qquad N\to \infty,
	\end{align}
and 
	\begin{align}\label{FN.asym3}
	D_N^B[\phi;\psi] 
	&= G[\phi]^NE[\phi]\Big(F[\phi;\psi]+O(\kappa^N)\Big),\qquad N\to \infty.
	\end{align}

After dividing by $a^N$, the difference between the series and the leading term is
	\begin{align*}
	\lefteqn{
		\sum_{n=0}^\infty (n+1)(n+N)^\omega a^{n}-\frac{N^\omega}{(1-a)^2}
		=
		\sum_{n=0}^\infty (n+1) a^{n}\Big((n+N)^\omega -N^\omega\Big)
	}\hspace{.5cm}
	\\
	&=
	\sum_{n=0}^\infty (n+1)^2 a^{n}O(\max\{(n+N)^{\mathrm{Re}(\omega)-1},N^{\mathrm{Re}(\omega)-1}\})
	=O(N^{\mathrm{Re}(\omega)-1}).
	\end{align*}
	This implies the estimate.
